def _are_adjacent(p1, p2):
    return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1]) == 1

def brute_min_path(grid, k):
    n = len(grid)
    # map value -> pos (values are 1..n*n unique)
    val_to_pos = {}
    for i in range(n):
        for j in range(n):
            val_to_pos[grid[i][j]] = (i, j)

    best = None
    # enumerate all walks of k cells
    def dfs(path_vals, r, c):
        nonlocal best
        # prune: if prefix already larger than best prefix, stop
        if best is not None:
            # compare prefix
            # if path_vals > best[:len(path_vals)] lexicographically, prune
            bpre = best[:len(path_vals)]
            if path_vals > bpre:
                return
        if len(path_vals) == k:
            if best is None or path_vals < best:
                best = list(path_vals)
            return
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n:
                path_vals.append(grid[nr][nc])
                dfs(path_vals, nr, nc)
                path_vals.pop()

    for i in range(n):
        for j in range(n):
            dfs([grid[i][j]], i, j)
    return best

def _is_valid_walk_values(grid, vals):
    if len(vals) == 0:
        return False
    n = len(grid)
    val_to_pos = {}
    for i in range(n):
        for j in range(n):
            val_to_pos[grid[i][j]] = (i, j)
    # all values in range
    for v in vals:
        if v not in val_to_pos:
            return False
    for a, b in zip(vals, vals[1:]):
        if not _are_adjacent(val_to_pos[a], val_to_pos[b]):
            return False
    return True

def _random_grid_strategy(n_min=2, n_max=3):
    # draw n then permutation
    return st.integers(min_value=n_min, max_value=n_max).flatmap(
        lambda n: st.permutations(list(range(1, n * n + 1))).map(
            lambda perm: [list(perm[i * n:(i + 1) * n]) for i in range(n)]
        )
    )

@given(grid=_random_grid_strategy(2, 3), k=st.integers(min_value=1, max_value=5))
def test_property_matches_brute_force(grid, k):
    assert minPath(grid, k) == brute_min_path(grid, k)
